pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint8 nCalls, uint128 seed) public {
        nCalls = uint8(bound(nCalls, 1, 20));
        uint contributed = 0;
        uint feesPaid = 0;
        for (uint i = 0; i < nCalls; i++) {
            address player = address(uint160(uint(keccak256(abi.encode(seed, i)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
            contributed += 10;
        }
        assertTrue(address(c).balance == c.pot(), "balance must equal pot");
    }
}
